function validate([s, part]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (typeof part !== 'string' || part.length < 1 || part.length > 1000) return 'part needs 1 to 1000 characters.';
  if (!/^[a-z]+$/.test(s) || !/^[a-z]+$/.test(part)) return 'Use lowercase English letters only.';
  return null;
}

