function removeOccurrences(s, part) {
  const m = part.length;
  const stack = [];
  for (const ch of s) {
    stack.push(ch);
    if (stack.length < m) {
      continue;
    }
    let matches = true;
    for (let j = 0; j < m; j++) {
      if (stack[stack.length - m + j] !== part[j]) {
        matches = false;
        break;
      }
    }
    if (matches) {
      stack.length -= m;
    }
  }
  return stack.join('');
}

