function removeOccurrences(s, part) {
  // Literally repeat the operation: find the leftmost copy and cut it out.
  let current = s;
  let at = current.indexOf(part);
  while (at !== -1) {
    current = current.slice(0, at) + current.slice(at + part.length);
    at = current.indexOf(part);
  }
  return current;
}

