function generate(rand, size) {
  const large = size === 'large';
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const alphabetSize = large ? 2 + Math.floor(rand() * 3) : 1 + Math.floor(rand() * 3);
  const pick = () => letters[Math.floor(rand() * alphabetSize)];
  const word = (length) => Array.from({ length }, pick).join('');
  const partLength = large ? (rand() < 0.15 ? 20 + Math.floor(rand() * 40) : 1 + Math.floor(rand() * 6)) : 1 + Math.floor(rand() * 4);
  const part = word(partLength);
  const limit = large ? 1000 : 2 + Math.floor(rand() * 12);
  // Start from a little noise, then keep inserting copies of part at random spots so removals cascade.
  let s = word(1 + Math.floor(rand() * Math.min(limit, large ? 30 : 4)));
  while (s.length + part.length <= limit) {
    const at = Math.floor(rand() * (s.length + 1));
    const piece = rand() < 0.8 ? part : word(1 + Math.floor(rand() * 3));
    s = s.slice(0, at) + piece + s.slice(at);
  }
  return [s, part];
}
